#include <algorithm>
#include <iomanip>
#include <iostream>
#include <vector>

struct Station {
    double distance;
    double price;
};

int main()
{
    double capacity, destination, average;
    int n;
    if (!(std::cin >> capacity >> destination >> average >> n))
        return 0;

    std::vector<Station> stations;
    for (int i = 0; i < n; ++i) {
        double price, distance;
        std::cin >> price >> distance;
        stations.push_back({distance, price});
    }
    stations.push_back({destination, 0.0});
    std::sort(stations.begin(), stations.end(),
              [](const Station &a, const Station &b) {
                  if (a.distance != b.distance)
                      return a.distance < b.distance;
                  return a.price < b.price;
              });

    // At the same position, only the lowest price can be useful.
    std::vector<Station> unique;
    for (const Station &s : stations) {
        if (unique.empty() || s.distance != unique.back().distance)
            unique.push_back(s);
    }
    stations.swap(unique);
    std::cout << std::fixed << std::setprecision(2);
    if (stations[0].distance != 0.0) {
        std::cout << "The maximum travel distance = 0.00\n";
        return 0;
    }

    double fuel = 0.0, cost = 0.0;
    const double range = capacity * average;
    const double EPS = 1e-9;
    int current = 0;
    while (current + 1 < static_cast<int>(stations.size())) {
        int next = -1;
        for (int j = current + 1; j < static_cast<int>(stations.size()); ++j) {
            if (stations[j].distance - stations[current].distance > range + EPS)
                break;
            if (next == -1 || stations[j].price < stations[next].price)
                next = j;
            if (stations[j].price < stations[current].price) {
                next = j;
                break;
            }
        }
        if (next == -1) {
            std::cout << "The maximum travel distance = "
                      << stations[current].distance + range << '\n';
            return 0;
        }

        double needed = (stations[next].distance - stations[current].distance) / average;
        double target = stations[next].price < stations[current].price ? needed : capacity;
        if (fuel < target) {
            cost += (target - fuel) * stations[current].price;
            fuel = target;
        }
        fuel -= needed;
        if (fuel < 0.0 && fuel > -EPS)
            fuel = 0.0;
        current = next;
    }
    std::cout << cost << '\n';
    return 0;
}
